?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>MSP Comercial</title><style>body{font-family:Arial;background:#f4f7fb;color:#17365d;margin:30px}.card{background:#fff;padding:20px;margin:16px 0;border:1px solid #d5deea;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #d5deea;padding:8px;text-align:left}h1{color:#12477d}</style></head><body><h1>MSP / Gestión comercial</h1><div class="card"><h2>Locales en vacancia</h2><?php if(!$vac):?><p>No hay vacancias abiertas.</p><?php else:?><table><tr><th>Local</th><th>Desde</th><th>Motivo</th><th>Estado</th></tr><?php foreach($vac as $v):?><tr><td><?=htmlspecialchars($v['cdo_local'].' - '.$v['desc_local'])?></td><td><?=$v['fecha_inicio']?></td><td><?=htmlspecialchars($v['motivo']??'—')?></td><td><?=$v['estado']?></td></tr><?php endforeach;?></table><?php endif;?></div><div class="card"><h2>Centro documental</h2><?php if(!$docs):?><p>No hay documentos activos.</p><?php else:?><table><tr><th>Archivo</th><th>Tipo</th><th>Contexto</th><th>Fecha</th></tr><?php foreach($docs as $d):?><tr><td><?=htmlspecialchars($d['nombre_archivo'])?></td><td><?=htmlspecialchars($d['tipo_documento'])?></td><td><?=htmlspecialchars('Contrato '.($d['id_contrato_arriendo']??'—').' / Local '.($d['id_local']??'—'))?></td><td><?=$d['fecha_registro']?></td></tr><?php endforeach;?></table><?php endif;?></div></body></html>
